<?php get_header();?><main class="wrap site-main"><h1><?php post_type_archive_title();?></h1><form class="inventory-filter" method="get"><input name="s" value="<?php echo esc_attr(get_search_query());?>" placeholder="Search make or model"><select name="cad_body"><option value="">Any body type</option><?php foreach(get_terms(['taxonomy'=>'cad_body','hide_empty'=>false]) as $term)printf('<option value="%s" %s>%s</option>',esc_attr($term->slug),selected(get_query_var('cad_body'),$term->slug,false),esc_html($term->name));?></select><button class="button">Search</button></form><?php if(have_posts()):?><div class="car-grid"><?php while(have_posts()):the_post();get_template_part('template-parts/car-card');endwhile;?></div><?php else:?><p>No vehicles matched your search.</p><?php endif;?></main><?php get_footer();
